import heapq


class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Every node needs one path to 0; one outgoing edge per node is enough, so threshold never binds.
        # Minimax Dijkstra from 0 over reversed edges.
        into = [[] for _ in range(n)]
        for a, b, w in edges:
            into[b].append((a, w))
        best = [None] * n
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if best[u] is not None:
                continue
            best[u] = d
            for v, w in into[u]:
                if best[v] is None:
                    heapq.heappush(heap, (max(d, w), v))
        return -1 if None in best else max(best)

